import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"卜居","description":"","frontmatter":{"title":"卜居","date":"2026-11-24T00:00:00.000Z","seq":24,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"远游·远游","link":"/blogs/楚辞/远游·远游.html"},"next":{"text":"渔父","link":"/blogs/楚辞/渔父.html"}},"headers":[],"relativePath":"blogs/楚辞/卜居.md","filePath":"blogs/楚辞/卜居.md"}'),l={name:"blogs/楚辞/卜居.md"};function r(p,e,n,_,c,i){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="卜居" tabindex="-1">卜居 <a class="header-anchor" href="#卜居" aria-label="Permalink to &quot;卜居&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　卜居</p><div class="poem"><p class="poem-stanza">屈原既放，三年不得复见。竭知尽忠而蔽障于谗。心烦虑乱，不知所从。乃往见太卜郑詹尹曰：“余有所疑，愿因先生决之。”詹尹乃端策拂龟，曰：“君将何以教之？”</p><p class="poem-stanza">屈原曰：“吾宁悃悃款款，朴以忠乎，将送往劳来，斯无穷乎？宁诛锄草茅以力耕乎，将游大人以成名乎？宁正言不讳以危身乎，将从俗富贵以偷生乎？宁超然高举以保真乎，将哫訾栗斯，喔咿儒儿，以事妇人乎？宁廉洁正直以自清乎，将突梯滑稽，如脂如韦，以洁楹乎？宁昂昂若千里之驹乎，将泛泛若水中之凫，与波上下，偷以全吾躯乎？宁与骐骥亢轭乎，将随驽马之迹乎？宁与黄鹄比翼乎，将与鸡鹜争食乎？此孰吉孰凶？何去何从？世溷浊而不清：蝉翼为重，千钧为轻黄钟毁弃，瓦釜雷鸣谗人高张，贤士无名。吁嗟默默兮，谁知吾之廉贞！”</p><p class="poem-stanza">詹尹乃释策而谢曰：“夫尺有所短，寸有所长物有所不足，智有所不明数有所不逮，神有所不通。用君之心，行君之意。龟策诚不能知此事。”</p></div>',3)])])}const u=t(l,[["render",r]]);export{d as __pageData,u as default};
